var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
// .NET 9: ValidateScopes is now on by default in Development — resolving a scoped
// service from a singleton factory throws. Register CacheService as scoped, or
// redesign the dependency. Disabling validation as a stopgap:
builder.Host.UseDefaultServiceProvider(options =>
{
    options.ValidateOnBuild = true;
    options.ValidateScopes = false;
});
builder.Services.AddSingleton<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));
// .NET 9: Default primary handler is now SocketsHttpHandler; cast to
// HttpClientHandler throws InvalidCastException. Use ConfigurePrimaryHttpMessageHandler.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new HttpClientHandler { UseCookies = false });
// .NET 9: Trace-level header logging now redacts all values by default.
// Allowlist non-sensitive headers you need to inspect for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h.Equals("Authorization", StringComparison.OrdinalIgnoreCase) ||
        h.Equals("Cookie", StringComparison.OrdinalIgnoreCase) ||
        h.Equals("Set-Cookie", StringComparison.OrdinalIgnoreCase)));
// .NET 9: ForwardedHeaders middleware now ignores X-Forwarded-* from proxies
// not in KnownProxies/KnownNetworks. Add your reverse proxy address(es).
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    options.KnownProxies.Add(System.Net.IPAddress.Parse("127.0.0.1"));
});
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

